'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const key='secureshop_agent_security';
const catalogButtonReady=({label,scope})=>[...document.querySelectorAll(scope+' button')].find(b=>{const s=getComputedStyle(b),r=b.getBoundingClientRect();return b.textContent.trim()===label&&!b.disabled&&s.visibility!=='hidden'&&s.display!=='none'&&Number(s.opacity)>0&&r.width>0&&r.height>0;});
const catalogPointerReady=e=>{const r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return !e.disabled&&(hit===e||e.contains(hit));};
async function qualifyMailHeaderCatalog({origin,user,admin,password,root,label,seedDisplay,objectiveId='ss_mail_header_construction',beforeProjection,expectedContent,browserSeconds=180}){
 const id=objectiveId;assert(['ss_mail_header_construction','ss_mail_reply_redirect','ss_mail_cross_persona_read'].includes(id));assert([180,600].includes(browserSeconds));
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'mailheadercatalog'),errors=[],blocked=[],screenshots=[];let page,adminPage;
 let expired=false;const deadline=setTimeout(()=>{expired=true;void browser.close().catch(()=>{});},browserSeconds*1000);
 const api=(p,url,method='GET',body)=>p.evaluate(async({url,method,body})=>{const r=await fetch(url,{method,headers:{authorization:'Bearer '+localStorage.getItem('token'),'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});return{status:r.status,body:await r.json()};},{url,method,body});
 const click=async(p,selector)=>{const e=await p.waitForSelector(selector,{visible:true});await e.evaluate(x=>x.scrollIntoView({block:'center',behavior:'instant'}));await p.waitForFunction(s=>{const e=document.querySelector(s),r=e?.getBoundingClientRect(),h=r&&document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return e&&!e.disabled&&(h===e||e.contains(h));},{timeout:15000},selector);await e.click();};
 const button=async(p,label,scope='body')=>{const h=await p.waitForFunction(catalogButtonReady,{timeout:15000,polling:'raf'},{label,scope});const e=h.asElement();assert.ok(e,label);await e.evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));await p.waitForFunction(catalogPointerReady,{timeout:15000},e);await e.click();};
 async function login(u){const c=await browser.createBrowserContext(),p=await c.newPage();await p.setViewport({width:1440,height:1100});await require('./fullBackendRenderedSecureShop').configurePage(p,origin,blocked,errors);await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.goto(origin+'/workshop-login');await p.waitForSelector('input[placeholder="Enter your username"]');await p.type('input[placeholder="Enter your username"]',u.username);await p.type('input[placeholder="Enter your password"]',password);await click(p,'button[type="submit"]');await p.waitForFunction(()=>localStorage.getItem('token')&&location.pathname!=='/workshop-login');return p;}
 const cardText=async p=>p.evaluate(()=>{const title=[...document.querySelectorAll('h3,.title')].find(e=>e.textContent.trim()==='SecureShop Agent Security');if(!title)return null;const card=title.parentElement.parentElement.parentElement;if(!card||card===document.body)return null;return card.innerText;});
 const count=async(p,n,total)=>p.waitForFunction(({n,total})=>{const title=[...document.querySelectorAll('h3,.title')].find(e=>e.textContent.trim()==='SecureShop Agent Security');const card=title?.parentElement.parentElement.parentElement;return card&&card!==document.body&&new RegExp(n+'\\s*/\\s*'+total+'|'+n+' of '+total).test(card.innerText);},{},{n,total});
 const screenshot=async(p,name)=>{await p.waitForFunction(()=>!document.querySelector('button[aria-label="Close hint"],button[aria-label="Close solution"]')&&document.getAnimations().filter(a=>a.effect?.getTiming().iterations!==Infinity).every(a=>a.playState==='finished'||a.playState==='idle'));
  const iframe=await p.$('iframe[title="SecureShop workshop"]');if(iframe){const frame=await iframe.contentFrame();await frame.waitForFunction(()=>!!document.querySelector('#ss-login-user,[aria-label="Account menu"],a[href="/secureshop/login"]'),{timeout:15000});}const filename=String(screenshots.length).padStart(2,'0')+'-'+name+'.png';await p.screenshot({path:path.join(root,filename),fullPage:true});screenshots.push(filename);};
 const exercise=async()=>{await page.goto(origin+'/workshop/secureshop');await page.waitForSelector('section[aria-label="Exercise objectives"]');await page.waitForFunction(label=>document.querySelector('section[aria-label="Exercise objectives"]').textContent.includes(label),{},label);};
 const gateVisible=async(kind,value)=>{await page.waitForFunction(({kind,value})=>[...document.querySelectorAll('section[aria-label="Exercise objectives"] button')].some(b=>b.textContent.trim()===kind)===value,{},{kind,value});};
 try{
  page=await login(user);adminPage=await login(admin);
  if(beforeProjection){await page.goto(origin+'/workshop/secureshop');await page.waitForSelector('section[aria-label="Exercise objectives"]');}else await exercise();const metadata=await api(page,'/api/auth/secureshop-launch');assert.equal(metadata.status,200);assert.ok(metadata.body.launch);const projection=beforeProjection?await beforeProjection({page,adminPage,api,button,click,exercise,count,login,launch:metadata.body.launch}):await seedDisplay({token:await page.evaluate(()=>localStorage.getItem('token')),launch:metadata.body.launch});
  for(const route of ['/workshop-dashboard','/workshop/challenges','/workshop/progress']){await page.goto(origin+route);await count(page,1,1);const currentTime=projection.readCurrentProjection?await projection.readCurrentProjection():projection;assert.ok((await cardText(page)).includes(currentTime.timeSpentSeconds<60?(route==='/workshop/challenges'?'< 1m':currentTime.timeSpentSeconds+'s'):Math.floor(currentTime.timeSpentSeconds/60)+'m'));if(route==='/workshop/progress')assert.equal(new URL(page.url()).pathname,'/workshop-dashboard');}
  const progress=await api(page,'/api/workshop/progress'),challenges=await api(page,'/api/workshop/challenges'),stats=await api(page,'/api/workshop/student/stats');const a=progress.body.challenges.find(x=>x.workshopKey===key),b=challenges.body.challenges.find(x=>x.workshopKey===key);assert.deepEqual(a,b);assert.equal(a.objectiveCount,1);assert.equal(a.completedObjectiveCount,1);assert.equal(stats.body.totalObjectives,1);assert.equal(stats.body.completedObjectives,1);await screenshot(page,'mail-header-catalog-dashboard');
  await exercise();assert.ok((await page.$eval('section[aria-label="Exercise objectives"]',e=>e.textContent)).includes('Completed: '+label));
  for(const kind of ['hint','solution']){const endpoint=kind==='hint'?'/api/hints/'+key+'/'+id:'/api/solutions/secureshop-agent-security/'+id;const response=page.waitForResponse(r=>new URL(r.url()).pathname===endpoint);await button(page,kind==='hint'?'Hint':'Solution','section[aria-label="Exercise objectives"]');const r=await response;assert.equal(r.status(),200);const content=(await r.json())[kind];if(expectedContent)assert.deepEqual(content,expectedContent[kind]);await page.waitForFunction(title=>document.querySelector('[role="dialog"]')?.textContent.includes(title),{},content.title);if(expectedContent){const segments=kind==='hint'?content.hints:[content.approach,...(content.examples||[]).flatMap(e=>[e.payload||e.prompt||e.action,e.explanation])].filter(Boolean);for(let index=0;index<segments.length;index++){if(kind==='hint'&&index>0)await button(page,'Next hint','[role="dialog"]');await page.waitForFunction(text=>document.querySelector('[role="dialog"] [data-testid="objective-help-content"]')?.textContent.includes(text),{},segments[index]);}}await click(page,'button[aria-label="Close '+kind+'"]');}
  await screenshot(page,'mail-header-catalog-objective');
  await adminPage.goto(origin+'/admin/exercises');const card='[data-exercise-key="'+key+'"]';await adminPage.waitForSelector(card);await button(adminPage,'Manage Objectives',card);const row='[data-objective-id="'+id+'"]';await adminPage.waitForSelector(row);assert.ok(await adminPage.$(row+' [title="Preview Solution"]'));await screenshot(adminPage,'mail-header-catalog-admin');
  const rowGate=async(h,s)=>adminPage.waitForFunction(({id,h,s})=>{const row=document.querySelector('[data-objective-id="'+id+'"]');if(!row)return false;const enabled=column=>getComputedStyle(row.children[column].firstElementChild).backgroundColor==='rgb(72, 187, 120)';return enabled(2)===h&&enabled(3)===s;},{},{id,h,s});
  const redirectedViews=[];
  const checkAdminAliases=async(h,s)=>{for(const alias of ['/admin/challenges','/admin/solutions']){await adminPage.goto(origin+alias);await adminPage.waitForFunction(()=>location.pathname==='/admin/exercises');await adminPage.waitForSelector(card);await button(adminPage,'Manage Objectives',card);await rowGate(h,s);redirectedViews.push({alias,resolved:'/admin/exercises',hint:h,solution:s});await screenshot(adminPage,'mail-header-admin-'+alias.split('/').pop()+'-'+Number(h)+Number(s));}};
  // Exercise each actual objective toggle once in each direction; remaining
  // combinations use canonical API mutations and inspect both redirected views.
  await click(adminPage,row+' > div:nth-child(3) > div');await rowGate(false,true);await exercise();await gateVisible('Hint',false);await gateVisible('Solution',true);await click(adminPage,row+' > div:nth-child(3) > div');await rowGate(true,true);
  await click(adminPage,row+' > div:nth-child(4) > div');await rowGate(true,false);await exercise();await gateVisible('Hint',true);await gateVisible('Solution',false);await click(adminPage,row+' > div:nth-child(4) > div');await rowGate(true,true);
  for(const [h,s] of [[false,false],[true,false],[false,true],[true,true]]){const base='/api/admin/exercises/'+key+'/objectives/'+id;assert.equal((await api(adminPage,base+'/hint','PATCH',{enabled:h})).status,200);assert.equal((await api(adminPage,base+'/solution','PATCH',{enabled:s})).status,200);await exercise();await gateVisible('Hint',h);await gateVisible('Solution',s);assert.equal((await api(page,'/api/hints/'+key+'/'+id)).status,h?200:403);assert.equal((await api(page,'/api/solutions/secureshop-agent-security/'+id)).status,s?200:403);await checkAdminAliases(h,s);}
  // Real admin master controls must change only their own help dimension.
  await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="solutions"]');await exercise();await gateVisible('Solution',false);await gateVisible('Hint',true);await checkAdminAliases(true,false);await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="solutions"]');await click(adminPage,card+' [data-control="hints"]');await exercise();await gateVisible('Hint',false);await gateVisible('Solution',true);await checkAdminAliases(false,true);await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="hints"]');
  assert.equal((await api(page,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:false})).status,403);assert.equal((await api(adminPage,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:false})).status,200);const hidden=await api(page,'/api/workshop/progress');const hiddenRow=hidden.body.challenges.find(x=>x.workshopKey===key);assert.equal(hiddenRow.objectiveCount,0);assert.equal(hiddenRow.completedObjectiveCount,0);assert.equal((await api(adminPage,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:true})).status,200);await page.goto(origin+'/workshop-dashboard');await count(page,1,1);
  await adminPage.goto(origin+'/admin/student-workshop-view?studentId='+user.id);await count(adminPage,1,1);const adminTime=projection.readCurrentProjection?await projection.readCurrentProjection():projection;assert.ok((await cardText(adminPage)).includes(adminTime.timeSpentSeconds<60?adminTime.timeSpentSeconds+'s':Math.floor(adminTime.timeSpentSeconds/60)+'m'));await screenshot(adminPage,'mail-header-catalog-admin-student');
  await exercise();if(projection.beforeReset)await projection.beforeReset();const reset=await require('./secureshopCouponFullAppBrowser').observeActionResponse(page,r=>new URL(r.url()).pathname.endsWith('/reset')&&r.request().method()==='POST',()=>button(page,'Reset launch'));assert.equal(reset.status(),200);if(projection.afterReset)await projection.afterReset();await page.goto(origin+'/workshop-dashboard');await count(page,0,1);assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);
  assert.equal(expired,false,'Owned browser deadline exceeded');return{status:'passed',controlledDisplayOnly:!beforeProjection,displayScope:projection.displayScope,actualActorCalls:projection.actorCalls||0,actualJudgeCalls:projection.judgeCalls||0,objectiveId:id,counts:{completed:1,total:1},nonzeroTime:projection.timeSpentSeconds,timingEvidence:projection.timingEvidence||'Controlled display timing fixture',completedStyle:true,renderedObjectiveHelpCombinations:4,actualObjectiveHintAndSolutionToggles:true,adminRedirectProjections:redirectedViews,scopedCardCounts:true,independentMasterHelpControls:true,reset:true,screenshots};
 }catch(error){if(page)await screenshot(page,'mail-header-catalog-failure').catch(()=>{});fs.writeFileSync(path.join(root,'mail-header-catalog-error.json'),JSON.stringify({message:error.message,errors,blocked}),{mode:0o600});throw error;}finally{clearTimeout(deadline);await browser.close();}
}
module.exports={qualifyMailHeaderCatalog,catalogButtonReady,catalogPointerReady};
